"""Tests for ea-records-opinion-character.l4, ea-proof.l4, ea-presumptions-burden.l4 and ea-parol-evidence.l4.
Expected values are read off the Act's text and illustrations (source/EA1893.txt), never off the encoding."""
import sys, os
sys.path.insert(0, os.path.dirname(__file__))
from fixtures import Types, Out

ROW = os.path.join(os.path.dirname(__file__), '..')
types = Types(os.path.join(ROW, 'ea-types.l4'), os.path.join(ROW, 'ea-cpc-interface.l4'))
def q(x): return '`%s`' % x
KP = 'the kind of proceedings'

# ---------------------------------------------------------------- records, judgments, opinion, character
o = Out(types, """IMPORT prelude
IMPORT `ea-cpc-interface`
IMPORT `ea-types`
IMPORT `ea-records-opinion-character`

-- Tests for ea-records-opinion-character.l4 (Evidence Act 1893, ss 34 to 57).
-- Expected values are read off the Act's text and illustrations.  Generated by generators/ea_tests_2.py.""")

o.section('34 to 41. Records')
o.case('s34 ill the account books', 'Record Facts', 'books of accounts regularly kept', 'refers to a matter into which the court has to inquire')
o.case('s34 ill the account books with other evidence', 'Record Facts', 'books of accounts regularly kept', 'refers to a matter into which the court has to inquire', 'other evidence to charge')
o.case('s34 not regularly kept', 'Record Facts', 'refers to a matter into which the court has to inquire')
o.assert_("`the entry in the books of accounts is relevant under section 34` `s34 ill the account books`")
o.assert_("NOT `the entry is sufficient to charge a person with liability` `s34 ill the account books`")
o.assert_("`the entry is sufficient to charge a person with liability` `s34 ill the account books with other evidence`")
o.assert_("NOT `the entry in the books of accounts is relevant under section 34` `s34 not regularly kept`")
o.case('s37 entry by a public officer', 'Record Facts', 'public or other official book, register or record', 'states a fact in issue or a relevant fact', 'made by a public officer in the discharge')
o.case('s37 entry not in a public record', 'Record Facts', 'states a fact in issue or a relevant fact', 'made by a public officer in the discharge')
o.assert_("`the entry in the public record is relevant under section 37` `s37 entry by a public officer`")
o.assert_("NOT `the entry in the public record is relevant under section 37` `s37 entry not in a public record`")
o.case('s38 published map', 'Record Facts', 'published map or chart generally offered for public sale')
o.case('s38 government plan', 'Record Facts', 'made under the authority of the Government')
o.case('s38 neither', 'Record Facts')
o.assert_("`the statement in the map, chart or plan is relevant under section 38` `s38 published map`")
o.assert_("`the statement in the map, chart or plan is relevant under section 38` `s38 government plan`")
o.assert_("NOT `the statement in the map, chart or plan is relevant under section 38` `s38 neither`")
for k, frag in [('Act or Ordinance', 'recital in an Act or Ordinance'), ('Malaysia or Commonwealth legislation', 'Parliament of Malaysia or the legislature of a part of the Commonwealth'), ('State of Malaysia', 'legislature of a State of Malaysia'), ('Gazette', 'purporting to be the Government Gazette')]:
    o.case('s39 recital in ' + k, 'Record Facts', 'court has to form an opinion as to the existence of a fact of a public nature', frag)
    o.assert_("`the recital is relevant under section 39` %s" % q('s39 recital in ' + k))
o.case('s39 recital but no public fact in question', 'Record Facts', 'recital in an Act or Ordinance')
o.assert_("NOT `the recital is relevant under section 39` `s39 recital but no public fact in question`")
o.case('s40 law book', 'Record Facts', 'court has to form an opinion as to a law of a country', 'book purporting to be printed or published under the authority')
o.case('s40 law report', 'Record Facts', 'court has to form an opinion as to a law of a country', 'ruling of the courts of that country')
o.assert_("`the statement of foreign law is relevant under section 40` `s40 law book`")
o.assert_("`the statement of foreign law is relevant under section 40` `s40 law report`")
o.case('s41 part of a longer document, whole not necessary', 'Record Facts', 'forms part of a longer statement')
o.case('s41 part of a longer document, whole necessary', 'Record Facts', 'forms part of a longer statement', 'court considers the whole of it necessary')
o.assert_("NOT `the whole of the longer statement or document must be proved under section 41` `s41 part of a longer document, whole not necessary`")
o.assert_("`the whole of the longer statement or document must be proved under section 41` `s41 part of a longer document, whole necessary`")

o.section('42 to 46. Judgments, orders and decrees')
o.case('s42 a judgment barring a second suit', 'Judgment Facts', 'prevents a court from taking cognizance', 'whether the court ought to take cognizance')
o.assert_("`the judgment is relevant under section 42` `s42 a judgment barring a second suit`")
o.case('s43 a probate judgment', 'Judgment Facts', 'final one of a competent court in the exercise of probate', 'confers on or takes away', 'legal character, or the title of that person to that thing, is relevant')
o.assert_("`the judgment is relevant under section 43(1)` `s43 a probate judgment`")
o.assert_("`the effect of a section 43 judgment` `s43 a probate judgment` EQUALS `conclusive proof`")
o.case('s43 a judgment not in the four jurisdictions', 'Judgment Facts', 'confers on or takes away', 'legal character, or the title of that person to that thing, is relevant')
o.assert_("NOT `the judgment is relevant under section 43(1)` `s43 a judgment not in the four jurisdictions`")
o.refused("`the effect of a section 43 judgment` `s43 a judgment not in the four jurisdictions`")
# section 44 illustration: a decree in a suit by A against C about a public right of way is relevant but not conclusive
o.case('s44 ill the right of way decree', 'Judgment Facts', 'relates to matters of a public nature relevant to the inquiry')
o.assert_("`the judgment is relevant under section 44` `s44 ill the right of way decree`")
# section 45 illustrations (a), (c), (d)
o.case('s45 ill a decree between other parties', 'Judgment Facts')
o.case('s45 ill c judgment shows motive', 'Judgment Facts', 'relevant under another provision of the Act')
o.case('s45 ill d previous conviction is a fact in issue', 'Judgment Facts', 'existence of the judgment, order or decree is a fact in issue')
o.assert_("NOT `the judgment, order or decree is relevant` `s45 ill a decree between other parties`")
o.assert_("`the judgment, order or decree is relevant` `s45 ill c judgment shows motive`")
o.assert_("`the judgment, order or decree is relevant` `s45 ill d previous conviction is a fact in issue`")
o.assert_("`the judgment, order or decree is relevant` `s42 a judgment barring a second suit`")
o.case('s46 fraud on a relevant judgment', 'Judgment Facts', 'relevant under section 42, 43 or 44 and has been proved by the adverse party', 'obtained by fraud or collusion')
o.assert_("`fraud, collusion or incompetence of the court may be shown under section 46` `s46 fraud on a relevant judgment`")

o.section('45A. Convictions and acquittals')
def cv(var, *true, kind='criminal proceedings', **v):
    o.case(var, 'Conviction Facts', *true, **{KP: kind})
cv('s45A conviction relevant to an issue', 'convicted or acquitted of an offence by or before a court in Singapore', 'relevant to an issue in the proceedings')
cv('s45A conviction on a plea of guilty', 'convicted or acquitted of an offence by or before a court in Singapore', 'relevant to an issue in the proceedings', 'convicted upon a plea of guilty')
cv('s45A conviction under appeal', 'convicted or acquitted of an offence by or before a court in Singapore', 'relevant to an issue in the proceedings', 'subject to review or appeal that has not yet been determined')
cv('s45A conviction quashed', 'convicted or acquitted of an offence by or before a court in Singapore', 'relevant to an issue in the proceedings', 'quashed or set aside')
cv('s45A conviction pardoned', 'convicted or acquitted of an offence by or before a court in Singapore', 'relevant to an issue in the proceedings', 'pardon has been given')
cv('s45A conviction not relevant to any issue', 'convicted or acquitted of an offence by or before a court in Singapore')
cv('s45A conviction barred as proof of disposition', 'convicted or acquitted of an offence by or before a court in Singapore', 'relevant to an issue in the proceedings', 'not admissible to prove a tendency or disposition')
cv('s45A same bar in a civil case', 'convicted or acquitted of an offence by or before a court in Singapore', 'relevant to an issue in the proceedings', 'not admissible to prove a tendency or disposition', kind='civil proceedings')
cv('s45A certificate of conviction', 'convicted or acquitted of an offence by or before a court in Singapore', 'relevant to an issue in the proceedings', 'certificate of conviction or acquittal is signed')
o.assert_("`the conviction is relevant and admissible under section 45A(2)` `s45A conviction relevant to an issue`")
o.assert_("`the conviction is relevant and admissible under section 45A(2)` `s45A conviction on a plea of guilty`")
o.assert_("NOT `the conviction is relevant and admissible under section 45A(2)` `s45A conviction under appeal`")
o.assert_("NOT `the conviction is relevant and admissible under section 45A(2)` `s45A conviction quashed`")
o.assert_("NOT `the conviction is relevant and admissible under section 45A(2)` `s45A conviction pardoned`")
o.assert_("NOT `the conviction is relevant and admissible under section 45A(2)` `s45A conviction not relevant to any issue`")
o.assert_("NOT `the conviction is relevant and admissible under section 45A(2)` `s45A conviction barred as proof of disposition`")
o.assert_("`the conviction is relevant and admissible under section 45A(2)` `s45A same bar in a civil case`")
o.assert_("`the conviction or acquittal is admissible under section 45A(1)` `s45A conviction under appeal`")
o.assert_("`the person is taken to have committed the acts and possessed the state of mind of the offence` `s45A conviction relevant to an issue`")
o.assert_("NOT `the person is taken to have committed the acts and possessed the state of mind of the offence` `s45A conviction quashed`")
o.assert_("`the conviction or acquittal may be proved by certificate` `s45A certificate of conviction`")
o.assert_("NOT `the conviction or acquittal may be proved by certificate` `s45A conviction relevant to an issue`")

o.section('47 to 53. Opinions')
o.case('s47 an expert whose help the court needs', 'Opinion Facts', 'likely to derive assistance', 'scientific, technical or other specialised knowledge based on training')
o.case('s47 an expert but not in the interests of justice', 'Opinion Facts', 'likely to derive assistance', 'scientific, technical or other specialised knowledge based on training', 'not be in the interests of justice')
o.case('s47 no assistance to the court', 'Opinion Facts', 'scientific, technical or other specialised knowledge based on training')
o.case('s47 not an expert', 'Opinion Facts', 'likely to derive assistance')
o.assert_("`the opinion of an expert is relevant under section 47` `s47 an expert whose help the court needs`")
o.assert_("NOT `the opinion of an expert is relevant under section 47` `s47 an expert but not in the interests of justice`")
o.assert_("NOT `the opinion of an expert is relevant under section 47` `s47 no assistance to the court`")
o.assert_("NOT `the opinion of an expert is relevant under section 47` `s47 not an expert`")
o.case('s48 ill a symptoms of other poisoned persons', 'Opinion Facts', 'supports or is inconsistent with a relevant opinion of an expert')
o.assert_("`the fact is relevant under section 48` `s48 ill a symptoms of other poisoned persons`")
o.case('s49 ill B C and D acquainted with the handwriting', 'Opinion Facts', 'person by whom a document was written or signed', 'acquainted with the handwriting', 'has seen that person write, or has received documents')
o.assert_("`the opinion on handwriting is relevant under section 49` `s49 ill B C and D acquainted with the handwriting`")
o.case('s50 ill kampong well', 'Opinion Facts', 'existence of a general custom or right', 'likely to know of its existence')
o.assert_("`the opinion on a general custom or right is relevant under section 50` `s50 ill kampong well`")
o.case('s51 usages and tenets', 'Opinion Facts', 'usages and tenets of a body of men', 'person having special means of knowledge on the subject')
o.assert_("`the opinion on usages, tenets or meanings is relevant under section 51` `s51 usages and tenets`")
o.case('s52 ill a treated as husband and wife', 'Opinion Facts', 'relationship of one person to another', 'expressed by conduct of a person who as a member of the family')
o.case('s52(2) prosecution under section 6A of the Women\'s Charter', 'Opinion Facts', 'relationship of one person to another', 'expressed by conduct of a person who as a member of the family', 'section 6A of the Women')
o.assert_("`the opinion expressed by conduct on a relationship is relevant under section 52` `s52 ill a treated as husband and wife`")
o.assert_("`the opinion is sufficient to prove a marriage` `s52 ill a treated as husband and wife`")
o.assert_("`the opinion expressed by conduct on a relationship is relevant under section 52` `s52(2) prosecution under section 6A of the Women's Charter`")
o.assert_("NOT `the opinion is sufficient to prove a marriage` `s52(2) prosecution under section 6A of the Women's Charter`")
o.case('s53 grounds of a relevant opinion', 'Opinion Facts', 'opinion of a living person is relevant')
o.assert_("`the grounds of the opinion are relevant under section 53` `s53 grounds of a relevant opinion`")

o.section('54 to 57. Character')
def ch(var, *true, kind='criminal proceedings'):
    o.case(var, 'Character Facts', *true, **{KP: kind})
ch('s54 civil character to prove conduct', 'render probable or improbable conduct imputed', kind='civil proceedings')
ch('s54 civil character appearing from facts otherwise relevant', 'render probable or improbable conduct imputed', 'character appears from facts otherwise relevant', kind='civil proceedings')
ch('s54 same fact in a criminal trial', 'render probable or improbable conduct imputed')
o.assert_("`the character evidence is irrelevant under section 54` `s54 civil character to prove conduct`")
o.assert_("NOT `the character evidence is irrelevant under section 54` `s54 civil character appearing from facts otherwise relevant`")
o.assert_("NOT `the character evidence is irrelevant under section 54` `s54 same fact in a criminal trial`")
ch('s55 good character of the accused', 'accused is of a good character')
ch('s55 good character in a civil case', 'accused is of a good character', kind='civil proceedings')
o.assert_("`the accused's good character is relevant under section 55` `s55 good character of the accused`")
o.assert_("NOT `the accused's good character is relevant under section 55` `s55 good character in a civil case`")
ch('s56 accused asks witnesses about good character; prosecution responds', 'accused or the accused\'s advocate asked a witness', 'prosecution or a person jointly charged')
ch('s56 accused gives evidence of good character; co-accused responds', 'accused gave evidence tending to establish', 'prosecution or a person jointly charged')
ch('s56 accused calls a character witness; prosecution responds with convictions', 'accused called a witness', 'prosecution or a person jointly charged', 'accused has previous convictions')
ch('s56 the accused has not put character in issue', 'prosecution or a person jointly charged', 'accused has previous convictions')
ch('s56 a stranger to the proceedings', 'accused gave evidence tending to establish')
o.assert_("`evidence of bad disposition or reputation may be called under section 56(2)` `s56 accused asks witnesses about good character; prosecution responds`")
o.assert_("`evidence of bad disposition or reputation may be called under section 56(2)` `s56 accused gives evidence of good character; co-accused responds`")
o.assert_("`evidence of previous convictions may be called under section 56(3)` `s56 accused calls a character witness; prosecution responds with convictions`")
o.assert_("NOT `evidence of previous convictions may be called under section 56(3)` `s56 accused asks witnesses about good character; prosecution responds`")
o.assert_("NOT `evidence of bad disposition or reputation may be called under section 56(2)` `s56 the accused has not put character in issue`")
o.assert_("NOT `evidence of bad disposition or reputation may be called under section 56(2)` `s56 a stranger to the proceedings`")
ch('s57 damages in a civil case', 'affect the amount of damages', kind='civil proceedings')
o.assert_("`the character evidence is relevant under section 57` `s57 damages in a civil case`")
ch('s57 expl general reputation', 'general reputation and general disposition')
ch('s57 expl particular acts', 'render probable or improbable conduct imputed')
o.assert_("`the form of the character evidence is permitted by the Explanation to section 57` `s57 expl general reputation`")
o.assert_("NOT `the form of the character evidence is permitted by the Explanation to section 57` `s57 expl particular acts`")
o.assert_("`the form of the character evidence is permitted by the Explanation to section 57` `s56 accused asks witnesses about good character; prosecution responds`")
o.write(os.path.join(ROW, 'ea-tests-records-opinion-character.l4'))

# ---------------------------------------------------------------- proof of documents
o = Out(types, """IMPORT prelude
IMPORT `ea-cpc-interface`
IMPORT `ea-types`
IMPORT `ea-proof`

-- Tests for ea-proof.l4 (Evidence Act 1893, ss 58 to 80B).
-- Expected values are read off the Act's text and illustrations.  Generated by generators/ea_tests_2.py.""")

o.section('58 to 60. Judicial notice and admitted facts')
o.case('s59 a fact of which notice is taken', 'Judicial Notice Facts', 'within section 59(1)(a) to (n)')
o.case('s59(2) public history', 'Judicial Notice Facts', 'public history, literature, science or art')
o.case('s60 admitted at the hearing', 'Judicial Notice Facts', 'agree to admit the fact at the hearing')
o.case('s60 admitted in writing before the hearing', 'Judicial Notice Facts', 'before the hearing, in a writing under their hands')
o.case('s60 deemed admitted by pleading', 'Judicial Notice Facts', 'deemed to have admitted the fact by their pleadings')
o.case('s60 admitted but court requires proof', 'Judicial Notice Facts', 'agree to admit the fact at the hearing', 'requires the admitted fact to be proved otherwise')
o.case('s60 not admitted', 'Judicial Notice Facts')
o.assert_("`the fact need not be proved because the court takes judicial notice of it` `s59 a fact of which notice is taken`")
o.assert_("NOT `the fact need not be proved because the court takes judicial notice of it` `s60 not admitted`")
o.assert_("`the court may resort to books or documents of reference` `s59(2) public history`")
o.assert_("`the court may resort to books or documents of reference` `s59 a fact of which notice is taken`")
o.assert_("`the fact need not be proved because it is admitted` `s60 admitted at the hearing`")
o.assert_("`the fact need not be proved because it is admitted` `s60 admitted in writing before the hearing`")
o.assert_("`the fact need not be proved because it is admitted` `s60 deemed admitted by pleading`")
o.assert_("NOT `the fact need not be proved because it is admitted` `s60 admitted but court requires proof`")
o.assert_("NOT `the fact need not be proved because it is admitted` `s60 not admitted`")

o.section('61 and 62. Oral evidence must be direct')
o.case('s61 contents of a document', 'Oral Evidence Facts', 'contents of a document')
o.case('s61 a fact seen', 'Oral Evidence Facts')
o.assert_("NOT `the fact may be proved by oral evidence` `s61 contents of a document`")
o.assert_("`the fact may be proved by oral evidence` `s61 a fact seen`")
o.case('s62 saw it', 'Oral Evidence Facts', 'refers to a fact which could be seen', 'witness says the witness saw that fact')
o.case('s62 did not see it', 'Oral Evidence Facts', 'refers to a fact which could be seen')
o.case('s62 heard it', 'Oral Evidence Facts', 'refers to a fact which could be heard', 'witness says the witness heard that fact')
o.case('s62 was told of it', 'Oral Evidence Facts', 'refers to a fact which could be heard')
o.case('s62 perceived it by another sense', 'Oral Evidence Facts', 'perceived by another sense or in another manner', 'perceived that fact by that sense')
o.case('s62 did not perceive it', 'Oral Evidence Facts', 'perceived by another sense or in another manner')
o.case('s62 the opinion of its holder', 'Oral Evidence Facts', 'refers to an opinion or to the grounds', 'that of the person who holds the opinion')
o.case('s62 an opinion held by another', 'Oral Evidence Facts', 'refers to an opinion or to the grounds')
o.case('s62(2) a treatise whose author is dead', 'Oral Evidence Facts', 'refers to an opinion or to the grounds', 'expressed in a treatise commonly offered for sale', 'author of the treatise is dead')
for v in ['s62 saw it', 's62 heard it', 's62 perceived it by another sense', 's62 the opinion of its holder', 's62(2) a treatise whose author is dead']:
    o.assert_("`the oral evidence is direct under section 62(1)` %s" % q(v))
for v in ['s62 did not see it', 's62 was told of it', 's62 did not perceive it', 's62 an opinion held by another']:
    o.assert_("NOT `the oral evidence is direct under section 62(1)` %s" % q(v))
o.assert_("`the opinion may be proved by production of the treatise under section 62(2)` `s62(2) a treatise whose author is dead`")

o.section('62A. Evidence through a live video or live television link')
def vl(var, *true, kind='civil proceedings'):
    o.case(var, 'Video Link Facts', *true, **{KP: kind})
vl('s62A child witness with permission', 'witness is below 18 years of age', 'court gives permission')
vl('s62A child witness without permission', 'witness is below 18 years of age')
vl('s62A agreed by the parties with permission', 'expressly agreed between the parties', 'court gives permission')
vl('s62A witness outside Singapore with permission', 'witness is outside Singapore', 'court gives permission')
vl('s62A expedient with permission', 'expedient in the interests of justice', 'court gives permission')
vl('s62A no ground though permission given', 'court gives permission')
vl('s62A child witness in a criminal matter', 'witness is below 18 years of age', 'court gives permission', kind='criminal proceedings')
vl('s62A child witness in a contempt proceeding', 'witness is below 18 years of age', 'court gives permission', 'proceedings for contempt of court')
for v in ['s62A child witness with permission', 's62A agreed by the parties with permission', 's62A witness outside Singapore with permission', 's62A expedient with permission']:
    o.assert_("`evidence may be given through a live video or live television link under section 62A(1)` %s" % q(v))
for v in ['s62A child witness without permission', 's62A no ground though permission given', 's62A child witness in a criminal matter', 's62A child witness in a contempt proceeding']:
    o.assert_("NOT `evidence may be given through a live video or live television link under section 62A(1)` %s" % q(v))
vl('s62A(6A) audio link only', 'all the parties to the civil proceedings expressly agree', 'describes the arrangements', 'court gives permission')
vl('s62A(6A) audio link, arrangements not described', 'all the parties to the civil proceedings expressly agree', 'court gives permission')
vl('s62A(6A) audio link in a criminal matter', 'all the parties to the civil proceedings expressly agree', 'describes the arrangements', 'court gives permission', kind='criminal proceedings')
o.assert_("`evidence may be given through a live audio link only under section 62A(6A)` `s62A(6A) audio link only`")
o.assert_("NOT `evidence may be given through a live audio link only under section 62A(6A)` `s62A(6A) audio link, arrangements not described`")
o.assert_("NOT `evidence may be given through a live audio link only under section 62A(6A)` `s62A(6A) audio link in a criminal matter`")
o.assert_("`the witness is deemed to give evidence in the presence of the court and in the proceedings` `s62A child witness with permission`")
o.assert_("`the witness is deemed to give evidence in the presence of the court and in the proceedings` `s62A(6A) audio link only`")
o.assert_("NOT `the witness is deemed to give evidence in the presence of the court and in the proceedings` `s62A child witness in a criminal matter`")

o.section('63 to 65. Primary and secondary evidence')
o.case('s64 the document itself', 'Document Facts', 'document itself is produced for the inspection of the court')
o.case('s64 expl 1 one of several parts', 'Document Facts', 'executed in several parts and the thing produced is one of the parts')
o.case('s64 expl 1 counterpart against the executing party', 'Document Facts', 'executed in counterpart and the thing produced is a counterpart offered against a party who executed it')
o.case('s64 expl 2 ill one placard to prove another', 'Document Facts', 'one of a number of documents all made by one uniform process')
o.case('s64 expl 2 ill a placard to prove the original', 'Document Facts', 'one of a number of documents all made by one uniform process', 'copies of a common original')
o.case('s64 expl 3 accurate electronic copy', 'Document Facts', 'copy of a document in the form of an electronic record and is shown to reflect that document accurately')
for v in ['s64 the document itself', 's64 expl 1 one of several parts', 's64 expl 1 counterpart against the executing party', 's64 expl 2 ill one placard to prove another', 's64 expl 3 accurate electronic copy']:
    o.assert_("`the thing produced is primary evidence of the document` %s" % q(v))
o.assert_("NOT `the thing produced is primary evidence of the document` `s64 expl 2 ill a placard to prove the original`")
o.case('s65(a) a certified copy', 'Document Facts', 'certified copy given under the provisions of the Act')
o.case('s65(b) a photocopy by a process that ensures accuracy', 'Document Facts', 'technical process that in itself ensures the accuracy')
o.case('s65(b) an electronic copy within Explanation 3', 'Document Facts', 'technical process that in itself ensures the accuracy', 'copy of a document in the form of an electronic record and is shown to reflect that document accurately')
o.case('s65(c) a copy compared with the original', 'Document Facts', 'made from or compared with the original')
o.case('s65(d) a counterpart against a party who did not execute it', 'Document Facts', 'counterpart offered against a party who did not execute it')
o.case('s65(e) an oral account by a person who saw the document', 'Document Facts', 'oral account of the contents given by a person who has himself or herself seen the document')
o.case('s65 ill e an oral account of a copy', 'Document Facts')
for v in ['s65(a) a certified copy', 's65(b) a photocopy by a process that ensures accuracy', 's65(c) a copy compared with the original', 's65(d) a counterpart against a party who did not execute it', 's65(e) an oral account by a person who saw the document']:
    o.assert_("`the thing produced is secondary evidence of the document` %s" % q(v))
o.assert_("NOT `the thing produced is secondary evidence of the document` `s65(b) an electronic copy within Explanation 3`")
o.assert_("NOT `the thing produced is secondary evidence of the document` `s65 ill e an oral account of a copy`")

o.section('66 to 68. When secondary evidence may be given')
o.case('s67(1)(a) held by the adverse party after notice', 'Document Facts', 'possession or power of the person against whom the document is sought to be proved', 'does not produce it', 'previously given the party in possession')
o.case('s67(1)(a) held by the adverse party, no notice', 'Document Facts', 'possession or power of the person against whom the document is sought to be proved', 'does not produce it')
o.case('s67(1)(a) held by the adverse party, notice dispensed with because it is in court', 'Document Facts', 'possession or power of the person against whom the document is sought to be proved', 'does not produce it', 'has the original in court')
o.case('s67(1)(a) held by a person beyond the process of the court', 'Document Facts', 'a person out of reach of or not subject to the process of the court', 'does not produce it', 'person in possession of the document is out of reach')
o.case('s67(1)(b) admitted in writing', 'Document Facts', 'admitted in writing by the person against whom it is proved')
o.case('s67(1)(c) lost', 'Document Facts', 'destroyed or lost')
o.case('s67(1)(c) cannot produce in reasonable time, not by own default', 'Document Facts', 'for a reason not arising from the party')
o.case('s67(1)(d) not easily movable', 'Document Facts', 'such a nature as not to be easily movable')
o.case('s67(1)(e) a public document', 'Document Facts', 'public document within the meaning of section 76')
o.case('s67(1)(f) certified copy permitted by law', 'Document Facts', 'certified copy is permitted by the Act')
o.case('s67(1)(g) numerous accounts', 'Document Facts', 'numerous accounts or other documents')
o.case('s66 no case applies', 'Document Facts')
