er('s116A(2) under the proponent\'s control', 'usual and ordinary course of business by a person who was not a party')
er('s116A(2) contrary evidence adduced', 'usual and ordinary course of business by a person who was not a party', 'did not generate, record or store it under the control', 'evidence to the contrary is adduced')
er('s116A(4)(a) the investigating officer is a party', 'usual and ordinary course of business by a person who was not a party', 'did not generate, record or store it under the control', 'police officer or other officer of a law enforcement agency')
er('s116A(4)(b) an accomplice is a party', 'usual and ordinary course of business by a person who was not a party', 'did not generate, record or store it under the control', 'accomplice of the accused person')
er('s116A(4) the same officer in a civil case', 'usual and ordinary course of business by a person who was not a party', 'did not generate, record or store it under the control', 'police officer or other officer of a law enforcement agency', kind='civil proceedings')
er('s116A(3) ill the record generated by the adverse party', 'generated, recorded or stored by a party adverse in interest')
er('s116A(6) an approved imaging process', 'approved process')
o.assert_("`the presumption under section 116A(1)` `s116A(1) a device that ordinarily produces the record` EQUALS JUST `the court is to presume`")
o.assert_("`the presumption under section 116A(1)` `s116A(1) doubt raised` EQUALS NOTHING")
o.assert_("`the presumption under section 116A(2)` `s116A(2) ill a neutral third party` EQUALS JUST `the court is to presume`")
o.assert_("`the presumption under section 116A(2)` `s116A(2) under the proponent's control` EQUALS NOTHING")
o.assert_("`the presumption under section 116A(2)` `s116A(2) contrary evidence adduced` EQUALS NOTHING")
o.assert_("`the presumption under section 116A(2)` `s116A(4)(a) the investigating officer is a party` EQUALS NOTHING")
o.assert_("`the presumption under section 116A(2)` `s116A(4)(b) an accomplice is a party` EQUALS NOTHING")
o.assert_("`the presumption under section 116A(2)` `s116A(4) the same officer in a civil case` EQUALS JUST `the court is to presume`")
o.assert_("`the presumption under section 116A(3)` `s116A(3) ill the record generated by the adverse party` EQUALS JUST `the court is to presume`")
o.assert_("`the presumption under section 116A(6)` `s116A(6) an approved imaging process` EQUALS JUST `the court is to presume`")
o.assert_("`the presumption under section 116A(6)` `s116A(1) doubt raised` EQUALS NOTHING")

o.section('103 to 113. Burden of proof')
def bf(var, *true): o.case(var, 'Burden Facts', *true)
bf('s104 ill a the claimant to land', 'would fail if no evidence at all were given on either side is the party who asserts')
bf('s104 ill b the defendant who alleges fraud')
o.assert_("`the burden lies on the party who asserts the fact under section 104` `s104 ill a the claimant to land`")
o.assert_("NOT `the burden lies on the party who asserts the fact under section 104` `s104 ill b the defendant who alleges fraud`")
bf('s105 no law places the proof elsewhere')
bf('s105 a law places the proof on a particular person', 'a law provides that the proof of the fact')
o.assert_("`the burden lies on the person who wishes the court to believe in the fact under section 105` `s105 no law places the proof elsewhere`")
o.assert_("NOT `the burden lies on the person who wishes the court to believe in the fact under section 105` `s105 a law places the proof on a particular person`")
bf('s106 ill a the dying declaration', 'necessary to be proved in order to enable a person to give evidence of another fact')
o.assert_("`the burden of proving the preliminary fact lies on the person who wishes to give the evidence` `s106 ill a the dying declaration`")
bf('s107 ill a unsoundness of mind', 'person is accused of an offence', 'general exception in the Penal Code')
bf('s107 ill c section 335 provocation', 'person is accused of an offence', 'special exception or proviso contained in another part of the Penal Code')
bf('s107 a proviso in the law defining the offence', 'person is accused of an offence', 'special exception or proviso contained in a law defining the offence')
bf('s107 not accused, a general exception', 'general exception in the Penal Code')
bf('s107 accused, no exception relied on', 'person is accused of an offence')
o.assert_("`the burden of proving the circumstance lies on the accused under section 107` `s107 ill a unsoundness of mind`")
o.assert_("`the burden of proving the circumstance lies on the accused under section 107` `s107 ill c section 335 provocation`")
o.assert_("`the burden of proving the circumstance lies on the accused under section 107` `s107 a proviso in the law defining the offence`")
o.assert_("NOT `the burden of proving the circumstance lies on the accused under section 107` `s107 not accused, a general exception`")
o.assert_("NOT `the burden of proving the circumstance lies on the accused under section 107` `s107 accused, no exception relied on`")
o.assert_("`the presumption under section 107` `s107 ill a unsoundness of mind` EQUALS JUST `the court is to presume`")
o.assert_("`the presumption under section 107` `s107 accused, no exception relied on` EQUALS NOTHING")
bf('s108 ill b the ticket', 'especially within the knowledge of a person')
o.assert_("`the burden lies on the person with special knowledge under section 108` `s108 ill b the ticket`")
o.assert_("NOT `the burden lies on the person with special knowledge under section 108` `s104 ill b the defendant who alleges fraud`")
bf('s109 alive within 30 years', 'was alive within 30 years')
bf('s110 not heard of for 7 years', 'has not been heard of for 7 years')
bf('s109 and s110 both made out', 'was alive within 30 years', 'has not been heard of for 7 years')
o.assert_("`the person bearing the burden on whether a person is alive` `s109 alive within 30 years` EQUALS JUST `the person who affirms that the person is dead`")
o.assert_("`the person bearing the burden on whether a person is alive` `s110 not heard of for 7 years` EQUALS JUST `the person who affirms that the person is alive`")
o.assert_("`the person bearing the burden on whether a person is alive` `s109 and s110 both made out` EQUALS JUST `the person who affirms that the person is alive`")
o.assert_("`the person bearing the burden on whether a person is alive` `s104 ill b the defendant who alleges fraud` EQUALS NOTHING")
bf('s111 partners who have acted as such', 'partners, landlord and tenant, or principal and agent')
bf('s112 owner in possession', 'owner of a thing of which the person is shown to be in possession')
bf('s113 ill a the attorney and client', 'position of active confidence')
o.assert_("`the burden lies on the person who affirms that the relationship has not existed or has ceased under section 111` `s111 partners who have acted as such`")
o.assert_("`the burden lies on the person who affirms that the person in possession is not the owner under section 112` `s112 owner in possession`")
o.assert_("`the burden of proving good faith lies on the party in a position of active confidence under section 113` `s113 ill a the attorney and client`")
o.assert_("NOT `the burden of proving good faith lies on the party in a position of active confidence under section 113` `s112 owner in possession`")
o.write(os.path.join(ROW, 'ea-tests-presumptions-burden.l4'))

# ---------------------------------------------------------------- parol evidence
o = Out(types, """IMPORT prelude
IMPORT `ea-cpc-interface`
IMPORT `ea-types`
IMPORT `ea-parol-evidence`

-- Tests for ea-parol-evidence.l4 (Evidence Act 1893, ss 93 to 102).
-- Expected values are read off the Act's text and illustrations.  Generated by generators/ea_tests_2.py.""")
o.case('s93 ill a contract in letters', 'Parol Evidence Facts', 'reduced by or by consent of the parties to the form of a document')
o.case('s93 matter required by law to be in writing', 'Parol Evidence Facts', 'required by law to be reduced to the form of a document')
o.case('s93 exception 1 public officer', 'Parol Evidence Facts', 'required by law to be reduced to the form of a document', 'public officer is required by law to be appointed in writing')
o.case('s93 exception 2 will admitted to probate', 'Parol Evidence Facts', 'reduced by or by consent of the parties to the form of a document', 'admitted to probate')
o.case('s93 expl 3 ill e the receipt, oral evidence of payment', 'Parol Evidence Facts', 'reduced by or by consent of the parties to the form of a document', 'fact other than the terms')
o.case('s93 not in a document', 'Parol Evidence Facts')
o.assert_("`section 93 confines proof to the document` `s93 ill a contract in letters`")
o.assert_("`section 93 confines proof to the document` `s93 matter required by law to be in writing`")
o.assert_("NOT `section 93 confines proof to the document` `s93 exception 1 public officer`")
o.assert_("NOT `section 93 confines proof to the document` `s93 exception 2 will admitted to probate`")
o.assert_("NOT `section 93 confines proof to the document` `s93 expl 3 ill e the receipt, oral evidence of payment`")
o.assert_("NOT `section 93 confines proof to the document` `s93 not in a document`")
b94 = ['terms of the document have been proved according to section 93', 'evidence is of an oral agreement or statement', 'offered as between the parties to the instrument', 'for the purpose of contradicting, varying, adding to or subtracting']
o.case('s94 ill b an oral agreement to postpone payment', 'Parol Evidence Facts', *b94)
o.case('s94(a) ill d misrepresentation invalidating the contract', 'Parol Evidence Facts', *(b94 + ['would invalidate the document']))
o.case('s94(b) ill g a verbal warranty', 'Parol Evidence Facts', *(b94 + ['separate oral agreement as to a matter on which the document is silent']))
o.case('s94(c) ill j a condition precedent', 'Parol Evidence Facts', *(b94 + ['condition precedent']))
o.case('s94(d) a subsequent oral modification, no formality required', 'Parol Evidence Facts', *(b94 + ['distinct subsequent oral agreement']))
o.case('s94(d) a subsequent oral modification of a contract required to be in writing', 'Parol Evidence Facts', *(b94 + ['distinct subsequent oral agreement', 'by law required to be in writing, or has been registered']))
o.case('s94(e) a usage consistent with the contract', 'Parol Evidence Facts', *(b94 + ['usage or custom']))
o.case('s94(e) a usage repugnant to the contract', 'Parol Evidence Facts', *(b94 + ['usage or custom', 'repugnant to or inconsistent']))
o.case('s94(f) how the language relates to existing facts', 'Parol Evidence Facts', *(b94 + ['shows in what manner the language of the document is related']))
o.case('s94 a non-party offers the evidence', 'Parol Evidence Facts', 'terms of the document have been proved according to section 93', 'evidence is of an oral agreement or statement', 'for the purpose of contradicting, varying, adding to or subtracting')
for v in ['s94 ill b an oral agreement to postpone payment', 's94(d) a subsequent oral modification of a contract required to be in writing', 's94(e) a usage repugnant to the contract']:
    o.assert_("`section 94 excludes the oral agreement or statement` %s" % q(v))
for v in ['s94(a) ill d misrepresentation invalidating the contract', 's94(b) ill g a verbal warranty', 's94(c) ill j a condition precedent', 's94(d) a subsequent oral modification, no formality required', 's94(e) a usage consistent with the contract', 's94(f) how the language relates to existing facts', 's94 a non-party offers the evidence']:
    o.assert_("NOT `section 94 excludes the oral agreement or statement` %s" % q(v))
o.case('s95 ill a $500 or $600', 'Parol Evidence Facts', 'ambiguous or defective')
o.case('s96 ill the Kranji estate', 'Parol Evidence Facts', 'plain in itself and applies accurately to existing facts')
o.case('s97 ill the plantation in Penang', 'Parol Evidence Facts', 'plain in itself but meaningless in reference to existing facts')
o.case('s98 ill a the white horse', 'Parol Evidence Facts', 'might have been meant to apply to any one')
o.case('s99 ill land at X in the occupation of Y', 'Parol Evidence Facts', 'applies partly to one set of existing facts and partly to another')
o.case('s100 ill all my mods', 'Parol Evidence Facts', 'meaning of illegible or not commonly intelligible characters')
o.case('s101 ill the tin and credit', 'Parol Evidence Facts', 'not a party to the document or a representative in interest', 'contemporaneous agreement varying the terms')
o.case('s101 a party gives the evidence', 'Parol Evidence Facts', 'contemporaneous agreement varying the terms')
o.case('s102 the construction of a will', 'Parol Evidence Facts', 'construction of a will')
o.assert_("`section 95 excludes evidence of facts showing the meaning or supplying the defects` `s95 ill a $500 or $600`")
o.assert_("`section 96 excludes evidence that the language was not meant to apply to the existing facts` `s96 ill the Kranji estate`")
o.assert_("`section 97 permits evidence that the language was used in a peculiar sense` `s97 ill the plantation in Penang`")
o.assert_("`section 98 permits evidence of facts showing to which person or thing the language applies` `s98 ill a the white horse`")
o.assert_("`section 99 permits evidence of which of 2 sets of facts the language was meant to apply to` `s99 ill land at X in the occupation of Y`")
o.assert_("`section 100 permits evidence of the meaning of the characters or expressions` `s100 ill all my mods`")
o.assert_("`section 101 permits the third person's evidence of a contemporaneous agreement` `s101 ill the tin and credit`")
o.assert_("NOT `section 101 permits the third person's evidence of a contemporaneous agreement` `s101 a party gives the evidence`")
o.assert_("`sections 93 to 101 do not apply because the question is the construction of a will` `s102 the construction of a will`")
o.assert_("NOT `section 95 excludes evidence of facts showing the meaning or supplying the defects` `s96 ill the Kranji estate`")
